import type {ProgressBarProps as PrimerProgressBarProps} from '@primer/react'
import {ProgressBar as PrimerProgressBar} from '@primer/react'
import {ColorByIndex} from './Shared'

import styles from './ProgressBar.module.css'
import {useMemo} from 'react'

interface Item {
  progress: number
  color?: string
  label?: string
}

export interface ProgressBarProps extends Omit<PrimerProgressBarProps, 'progress'> {
  data: Item[]
  'aria-label'?: string
}

function ProgressBar({data, 'aria-label': ariaLabel, ...restProps}: ProgressBarProps) {
  const items = useMemo(() => {
    return data.map((item, index) => {
      const color = item.color ?? ColorByIndex(index)
      const label = item.label

      return (
        <PrimerProgressBar.Item
          role="progressbar"
          // eslint-disable-next-line @eslint-react/no-array-index-key
          key={index}
          progress={item.progress}
          style={{backgroundColor: color}}
          aria-label={label}
        />
      )
    })
  }, [data])

  const valueNow = useMemo(() => {
    return data.reduce((acc, item) => acc + item.progress, 0)
  }, [data])

  return (
    <PrimerProgressBar aria-valuenow={valueNow} {...restProps} className={styles.PrimerProgressBar}>
      {items}
    </PrimerProgressBar>
  )
}

ProgressBar.displayName = 'DataCard.ProgressBar'

ProgressBar.Item = PrimerProgressBar.Item

export default ProgressBar
